"use strict";
import { useState } from "react";
import { AnimatedPopover, Flex, Popover, Text } from "ui/src";
import { CheckCircleFilled, Options } from "ui/src/components/icons";
import { useModifyLockContext } from "../ModifyLockContextProvider";
export default function MobileOptionsPopover({ options }) {
  const { activeOption, setActiveOption } = useModifyLockContext();
  const [isOpen, setIsOpen] = useState(false);
  const handleToggleOptions = (option) => {
    setIsOpen(false);
    setActiveOption(option);
  };
  return <Popover>
      <Popover.Trigger onPress={() => setIsOpen(!isOpen)}>
        <Flex
    display="none"
    $md={{ display: "flex", flexDirection: "row", justifyContent: "space-between" }}
    py={"$spacing12"}
    gap={"$gap8"}
  >
          <Text variant="buttonLabel3">{activeOption}</Text>
          <button role="button" className="button-clear">
            <Options size={20} />
          </button>
        </Flex>
        <AnimatedPopover isOpen={isOpen}>
          <Flex flexDirection="column" gap={"$gap12"} $md={{ pb: "$spacing24", px: "$spacing12" }}>
            {options.map((option) => <Popover.Close key={option} asChild>
                <button key={option} role="button" className="button-clear" onClick={() => handleToggleOptions(option)}>
                  <Flex row alignItems="center" gap={"$gap12"}>
                    <Text variant="buttonLabel2">{option}</Text>
                    {activeOption === option && <CheckCircleFilled size={16} />}
                  </Flex>
                </button>
              </Popover.Close>)}
          </Flex>
        </AnimatedPopover>
      </Popover.Trigger>
    </Popover>;
}
